/// Answers every request with a greeting that echoes the path and authority
/// it arrived with (WASI folds the `Host` header into the request authority).
/// When a co-located caller reaches this component through same-host local
/// routing, the echoed host is the authority the caller dialed (e.g.
/// `callee.internal`) — a hostname that resolves nowhere on the real network.
#[wstd::http_server]
async fn main(req: Request<Body>) -> Result<Response<Body>, wstd::http::Error> {
    let host = req
        .uri()
        .authority()
        .map(|authority| authority.as_str())
        .unwrap_or("<none>");
    let body = format!(
        "hello from the callee! (path: {}, host: {})\n",
        req.uri().path(),
        host
    );
    Response::builder()
        .status(StatusCode::OK)
        .body(Body::from(body))
        .context("building response")
}

use wstd::http::error::Context;
use wstd::http::{Body, Client, Request, Response, StatusCode};

/// Calls the callee over `wasi:http/outgoing-handler` and reports what
/// happened. The target URL is resolved in order from:
///
/// 1. a `?url=<target>` query parameter,
/// 2. the `CALLEE_URL` environment variable,
/// 3. `http://callee.internal/hello` — a hostname that resolves nowhere on
///    the real network, so the call only succeeds when the host serves it
///    via same-host local routing (`--http-local-routing` on the host, plus a
///    co-located callee whose `wasi:http/incoming-handler` config registers
///    that authority in `localRoute` with "callee.internal/hello" as the path).
#[wstd::http_server]
async fn main(req: Request<Body>) -> Result<Response<Body>, wstd::http::Error> {
    let target = req
        .uri()
        .query()
        .and_then(|q| q.split('&').find_map(|pair| pair.strip_prefix("url=")))
        .map(str::to_string)
        .or_else(|| std::env::var("CALLEE_URL").ok())
        .unwrap_or_else(|| "http://callee.internal/hello".to_string());

    let outgoing = match Request::get(&target).body(Body::empty()) {
        Ok(outgoing) => outgoing,
        Err(e) => {
            return respond(
                StatusCode::BAD_REQUEST,
                format!("invalid target url {target}: {e}\n"),
            );
        }
    };

    match Client::new().send(outgoing).await {
        Ok(mut resp) => {
            let status = resp.status();
            let upstream = match resp.body_mut().str_contents().await {
                Ok(contents) => contents.to_string(),
                Err(e) => format!("<unreadable body: {e}>"),
            };
            respond(
                StatusCode::OK,
                format!("caller -> {target}\nupstream status: {status}\nupstream body: {upstream}"),
            )
        }
        Err(e) => respond(
            StatusCode::BAD_GATEWAY,
            format!("caller -> {target}\nrequest failed: {e}\n"),
        ),
    }
}

fn respond(status: StatusCode, body: String) -> Result<Response<Body>, wstd::http::Error> {
    Response::builder()
        .status(status)
        .body(Body::from(body))
        .context("building response")
}

//! Order processing over JetStream, with replay.
//!
//! Two paths share one component. The host pushes new deliveries into
//! `handle-message`, and the same component can replay history from an
//! arbitrary stream sequence with `scan`.
//!
//! Every `wasmcloud:nats` function is an `async func`, so this is a WASI P3
//! component: the handler is an `async fn` that awaits its imports from inside
//! the delivery, and the host keeps delivering to the same instance while it
//! does.

wit_bindgen::generate!({
    path: "wit",
    world: "nats-jetstream-replay",
    generate_all,
});

use exports::wasmcloud::nats::jetstream_handler::Guest as JetstreamHandler;
use wasmcloud::nats::jetstream::{self, MessageHandle};
use wasmcloud::nats::kv;
use wasmcloud::nats::types::{HeaderEntry, NatsError, NatsMessage};

/// Bucket holding the running per-order totals.
const TOTALS_BUCKET: &str = "order-totals";
/// Subject the processed-order notification is published to.
const PROCESSED_SUBJECT: &str = "orders.processed";

struct Component;

/// Renders an error for the handler's `result<_, string>`.
fn describe(err: &NatsError) -> String {
    match err {
        NatsError::Connection(detail) => format!("connection: {detail}"),
        NatsError::Timeout(detail) => format!("timeout: {detail}"),
        NatsError::NoResponders => "no responders on subject".to_string(),
        NatsError::Denied(denial) => format!(
            "{:?} `{}` is outside this workload's grant ({:?}); the host declares the grants, \
             so widening one is the operator's call",
            denial.target, denial.name, denial.reason
        ),
        NatsError::MaxPayloadExceeded(limit) => format!("payload exceeds server limit {limit}"),
        NatsError::Jetstream(detail) => format!("jetstream: {detail}"),
        NatsError::KeyNotFound => "key not found".to_string(),
        NatsError::RevisionMismatch(current) => format!("revision mismatch, current {current}"),
        NatsError::NoMessages => "no messages".to_string(),
        NatsError::NotFound(what) => format!("not found: {what}"),
        NatsError::UnsupportedByServer(detail) => format!("unsupported by server: {detail}"),
        NatsError::Disconnected => "disconnected".to_string(),
        NatsError::AlreadySettled => "message already settled".to_string(),
        // This example runs `ack-mode: auto`, so a settle from here is the
        // host's to make.
        NatsError::AckOwnedByHost => {
            "acknowledgement is the host's under `ack-mode: auto`".to_string()
        }
        NatsError::InvalidHeader(detail) => format!("invalid header: {detail}"),
        NatsError::LimitExceeded(detail) => format!("limit exceeded: {detail}"),
        NatsError::Unexpected(detail) => format!("unexpected: {detail}"),
    }
}

/// A key's running total and the stream sequence that last contributed to it.
///
/// Storing the sequence alongside the total is what makes the update
/// idempotent. Adding on every delivery is not: at-least-once means the same
/// order arrives again after any failure downstream of the write, and a bare
/// `total += amount` counts it twice.
struct Total {
    running: u64,
    last_sequence: u64,
}

fn parse_total(raw: &[u8]) -> Option<Total> {
    let text = std::str::from_utf8(raw).ok()?;
    let (running, last_sequence) = text.trim().split_once('@')?;
    Some(Total {
        running: running.trim().parse().ok()?,
        last_sequence: last_sequence.trim().parse().ok()?,
    })
}

fn encode_total(total: &Total) -> Vec<u8> {
    format!("{}@{}", total.running, total.last_sequence).into_bytes()
}

/// Adds an order's amount to the running total, exactly once per sequence.
///
/// `update` is compare-and-swap on revision, and a mismatch carries the current
/// revision, so a retry does not need a re-read. Two concurrent handlers on the
/// same key therefore converge instead of silently losing a write, which is
/// what a last-write-wins `put` would do here.
async fn accumulate(
    bucket: &kv::Bucket,
    key: &str,
    amount: u64,
    sequence: u64,
) -> Result<u64, NatsError> {
    let mut attempt = 0;
    loop {
        attempt += 1;
        // A key that was never written is `key-not-found`, not an
        // absent-but-ok result: the first order for an id takes the `create`
        // path below, every later one takes `update`.
        let current = match bucket.get(key.to_string()).await {
            Ok(entry) => Some(entry),
            Err(NatsError::KeyNotFound) => None,
            Err(e) => return Err(e),
        };
        let (existing, revision) = match &current {
            Some(entry) => (parse_total(&entry.value), entry.revision),
            None => (None, 0),
        };

        // This sequence is already counted, so this is a redelivery. Report the
        // total unchanged rather than adding again.
        if let Some(total) = &existing
            && sequence <= total.last_sequence
        {
            return Ok(total.running);
        }

        let next = Total {
            running: existing
                .as_ref()
                .map_or(0, |t| t.running)
                .saturating_add(amount),
            last_sequence: sequence,
        };
        let encoded = encode_total(&next);

        let result = if current.is_some() {
            bucket
                .update(key.to_string(), encoded.clone(), revision)
                .await
        } else {
            bucket.create(key.to_string(), encoded.clone()).await
        };

        match result {
            Ok(_) => return Ok(next.running),
            // Someone else wrote between the read and the write. Re-read and
            // reapply rather than clobbering their value.
            Err(NatsError::RevisionMismatch(_)) if attempt < 5 => continue,
            Err(e) => return Err(e),
        }
    }
}

/// Reads `order-id:amount` out of a message body.
fn parse_order(body: &[u8]) -> Option<(String, u64)> {
    let text = std::str::from_utf8(body).ok()?;
    let (id, amount) = text.trim().split_once(':')?;
    if id.is_empty() {
        return None;
    }
    Some((id.to_string(), amount.trim().parse().ok()?))
}

impl JetstreamHandler for Component {
    /// Processes one delivery.
    ///
    /// Delivery is at-least-once: a redelivery after a partial failure calls
    /// this again with the same body, so the work must be idempotent. The
    /// `delivery-count` check below is what makes the retry visible rather
    /// than silent.
    async fn handle_message(handle: MessageHandle) -> Result<(), String> {
        let message = handle.message();
        let sequence = handle.sequence();
        let delivery = handle.delivery_count();

        let Some((order_id, amount)) = parse_order(&message.body) else {
            // A malformed body will never parse, so returning `Err` would nak
            // it and have it redelivered forever. Under `ack-mode: auto` the
            // host owns the acknowledgement and `term()` is not the guest's to
            // call, so report success and let the message be dropped. Bind with
            // `ack-mode: manual` to term it explicitly instead.
            println!("dropping malformed order at sequence {sequence}");
            return Ok(());
        };

        if delivery > 1 {
            println!("order {order_id} redelivered (attempt {delivery})");
        }

        let bucket = kv::open(TOTALS_BUCKET.to_string())
            .await
            .map_err(|e| describe(&e))?;
        let running = accumulate(&bucket, &order_id, amount, sequence)
            .await
            .map_err(|e| describe(&e))?;

        // `Nats-Msg-Id` deduplicates within the stream's duplicate window, so a
        // redelivered order does not publish a second notification. The window
        // is stream configuration, not a guarantee the interface makes.
        let notification = NatsMessage {
            subject: PROCESSED_SUBJECT.to_string(),
            body: format!("{order_id}:{running}").into_bytes(),
            reply_to: None,
            headers: Some(vec![HeaderEntry {
                name: "Nats-Msg-Id".to_string(),
                value: format!("processed-{order_id}-{sequence}"),
            }]),
        };
        let ack = jetstream::publish(notification)
            .await
            .map_err(|e| describe(&e))?;

        println!(
            "order {order_id} +{amount} -> {running} (stream seq {}, duplicate: {})",
            ack.sequence, ack.duplicate
        );

        // Returning Ok is what acks under `ack-mode: auto`. Under `manual` the
        // handler would call `handle.ack()` itself.
        Ok(())
    }
}

export!(Component);

//! HTTP Basic authentication for the registry.
//!
//! Credentials come from a host component plugin (the secrets backend), imported
//! as `wasmcloud:secrets/store` and unwrapped with `wasmcloud:secrets/reveal`.
//! Every request must carry a matching `Authorization: Basic` header — including
//! the `GET /v2/` probe, which is where an OCI client discovers it must
//! authenticate.

use base64::Engine as _;
use base64::engine::general_purpose::STANDARD;
use sha2::{Digest, Sha256};

use crate::bindings::wasmcloud::secrets::reveal::reveal;
use crate::bindings::wasmcloud::secrets::store::{self, SecretValue};
use crate::http::{header_str, respond};
use crate::{Fields, Response};

/// Config keys the secrets backend is expected to serve.
const USERNAME_KEY: &str = "registry-username";
const PASSWORD_KEY: &str = "registry-password";
const REALM: &str = "wasmcloud-oci-registry";

/// Returns `Some(challenge)` — a `401` with a `WWW-Authenticate: Basic` header —
/// when the request is not authenticated, and `None` when the credentials match.
pub(crate) async fn require_basic(headers: &Fields) -> Option<Response> {
    let (Some(username), Some(password)) = (
        secret_string(USERNAME_KEY).await,
        secret_string(PASSWORD_KEY).await,
    ) else {
        // The backend did not supply both credentials; deny rather than serve
        // the registry without authentication.
        return Some(challenge());
    };
    let expected = STANDARD.encode(format!("{username}:{password}"));
    match header_str(headers, "authorization").and_then(|h| basic_token(&h)) {
        Some(actual) if tokens_match(&actual, &expected) => None,
        _ => Some(challenge()),
    }
}

/// Fetch a credential from the secrets backend and reveal it as a UTF-8 string.
async fn secret_string(key: &str) -> Option<String> {
    let secret = store::get(key.to_string()).await.ok()?;
    match reveal(&secret).await {
        SecretValue::String(value) => Some(value),
        SecretValue::Bytes(bytes) => String::from_utf8(bytes).ok(),
    }
}

/// Extract the base64 credential token from an `Authorization: Basic <token>`
/// header. The scheme is matched case-insensitively per RFC 7617; any other
/// scheme (or a header without a token) yields `None`.
fn basic_token(header: &str) -> Option<String> {
    let (scheme, token) = header.trim().split_once(' ')?;
    scheme
        .eq_ignore_ascii_case("Basic")
        .then(|| token.trim().to_string())
}

/// Constant-time credential comparison that leaks neither the value nor its
/// length: each token is hashed to a fixed 32 bytes and the digests are compared
/// byte-for-byte, so the work done is independent of the inputs. Equal digests
/// imply equal tokens (SHA-256 is collision resistant).
fn tokens_match(actual: &str, expected: &str) -> bool {
    let actual = Sha256::digest(actual.as_bytes());
    let expected = Sha256::digest(expected.as_bytes());
    let mut diff = 0u8;
    for (a, b) in actual.iter().zip(expected.iter()) {
        diff |= a ^ b;
    }
    diff == 0
}

fn challenge() -> Response {
    let header = format!("Basic realm=\"{REALM}\"");
    respond(
        401,
        &[
            ("www-authenticate", header.as_str()),
            ("content-type", "application/json"),
            ("docker-distribution-api-version", "registry/2.0"),
        ],
        br#"{"errors":[{"code":"UNAUTHORIZED","message":"authentication required"}]}"#.to_vec(),
    )
}

//! Blob content operations: serving (`GET`/`HEAD`/`DELETE`), streaming uploads
//! with digest verification, and cross-repository mount.

use crate::bindings;
use crate::http::{error_response, method_not_allowed, respond, respond_owned, stream_response};
use crate::keys::blob_key;
use crate::storage::{
    blob_err, copy_object, delete_object, has_object, object_size, open_object_stream,
};
use crate::uploads::begin_upload_session;
use crate::{Container, Method, Request, Response};
use sha2::{Digest, Sha256};

pub(crate) async fn handle_blob(
    container: &Container,
    method: &Method,
    name: &str,
    digest: &str,
) -> Result<Response, String> {
    let key = blob_key(name, digest);

    match method {
        Method::Get | Method::Head => {
            if !has_object(container, &key).await? {
                return Ok(error_response(404, "BLOB_UNKNOWN", "blob unknown"));
            }
            let size = object_size(container, &key).await?;
            let headers = vec![
                (
                    "content-type".to_string(),
                    "application/octet-stream".to_string(),
                ),
                ("docker-content-digest".to_string(), digest.to_string()),
                ("content-length".to_string(), size.to_string()),
            ];
            if matches!(method, Method::Head) {
                // HEAD carries no body, so Content-Length is omitted (a declared
                // length with an empty body is rejected by the runtime).
                return Ok(respond_owned(
                    200,
                    headers.into_iter().take(2).collect(),
                    Vec::new(),
                ));
            }
            // Stream the blob straight from the blobstore into the HTTP response
            // body: the reader returned by `get-data` is handed to the response
            // unchanged, so bytes never pass through a guest-side buffer.
            let body = open_object_stream(container, &key, size).await?;
            Ok(stream_response(200, headers, body))
        }
        Method::Delete => {
            if !has_object(container, &key).await? {
                return Ok(error_response(404, "BLOB_UNKNOWN", "blob unknown"));
            }
            delete_object(container, &key).await?;
            Ok(respond(202, &[], Vec::new()))
        }
        _ => Ok(method_not_allowed()),
    }
}

/// Cross-repository blob mount: if `digest` exists in the `from` repository,
/// copy it into `name` and return `201`; otherwise fall back to a normal upload
/// session (`202`), as the spec permits.
pub(crate) async fn mount_blob(
    container: &Container,
    name: &str,
    digest: &str,
    from: &str,
) -> Result<Response, String> {
    let source = blob_key(from, digest);
    if !has_object(container, &source).await? {
        return begin_upload_session(container, name).await;
    }
    let dest = blob_key(name, digest);
    // Content-addressed, so skip the copy if the target repo already has it.
    if !has_object(container, &dest).await? {
        copy_object(&source, &dest).await?;
    }
    Ok(blob_created(name, digest))
}

/// Stream an upload straight into the blobstore, hashing as bytes flow and
/// verifying the digest at end-of-stream. `prior` bytes (buffered from earlier
/// PATCH chunks) are written first; a monolithic upload passes an empty `prior`
/// and never buffers the blob.
///
/// Blobs are content-addressed, so an existing object at the target key is
/// already exactly `expected` and is left untouched (idempotent). Only a blob
/// this call newly created is removed on a digest mismatch, so a bad push can
/// never clobber a previously-stored blob. (A concurrent first-time push of the
/// same digest where one side sends mismatched content is not guarded — an
/// example-acceptable edge; a production registry would stage to a temp key.)
pub(crate) async fn stream_and_finalize(
    container: &Container,
    name: &str,
    expected: &str,
    prior: Vec<u8>,
    request: Request,
) -> Result<Response, String> {
    let key = blob_key(name, expected);

    // Already present (content-addressed) — accept without rewriting; the request
    // body is dropped unread.
    if has_object(container, &key).await? {
        return Ok(blob_created(name, expected));
    }

    let (res_tx, res_rx) = bindings::wit_future::new(|| Ok(()));
    let (mut body, _trailers) = Request::consume_body(request, res_rx);
    let (mut tx, rx) = bindings::wit_stream::new();

    // The writer task tees the request body into the blobstore stream (`tx`) and
    // a running hasher; the digest is stored before `tx` is dropped so it's
    // visible once `write_data` (which drains `rx`) returns.
    let digest_cell = std::rc::Rc::new(std::cell::RefCell::new(String::new()));
    let writer_digest = digest_cell.clone();
    wit_bindgen::spawn_local(async move {
        let mut hasher = Sha256::new();
        if !prior.is_empty() {
            hasher.update(&prior);
            let _ = tx.write_all(prior).await;
        }
        loop {
            let (status, chunk) = body.read(Vec::with_capacity(64 * 1024)).await;
            if !chunk.is_empty() {
                hasher.update(&chunk);
                let _ = tx.write_all(chunk).await;
            }
            if matches!(status, wit_bindgen::StreamResult::Dropped) {
                break;
            }
        }
        *writer_digest.borrow_mut() = format!("sha256:{}", hex::encode(hasher.finalize()));
        drop(tx);
        drop(res_tx);
    });

    container
        .write_data(key.clone(), rx)
        .await
        .map_err(blob_err)?;

    let actual = digest_cell.borrow().clone();
    if actual != expected {
        // Remove the just-written object whose contents didn't match the claimed
        // digest (it can only be the blob this call created — see the doc above).
        let _ = delete_object(container, &key).await;
        return Ok(error_response(
            400,
            "DIGEST_INVALID",
            "provided digest did not match uploaded content",
        ));
    }

    Ok(blob_created(name, expected))
}

/// The `201 Created` response returned once a blob is committed at its digest.
fn blob_created(name: &str, digest: &str) -> Response {
    respond_owned(
        201,
        vec![
            ("location".to_string(), format!("/v2/{name}/blobs/{digest}")),
            ("docker-content-digest".to_string(), digest.to_string()),
        ],
        Vec::new(),
    )
}

//! Response construction and request-body handling over `wasi:http@0.3.0`.

use crate::bindings;
use crate::{Fields, Request, Response};

/// Read a header's first value as a UTF-8 string.
pub(crate) fn header_str(headers: &Fields, name: &str) -> Option<String> {
    headers
        .get(name)
        .into_iter()
        .next()
        .and_then(|value| String::from_utf8(value).ok())
}

/// Consume the request body into memory.
pub(crate) async fn read_request_body(request: Request) -> Vec<u8> {
    // `res` lets the guest signal an error back upstream; we always succeed, so
    // dropping the writer resolves it to `Ok(())` via the default.
    let (res_tx, res_rx) = bindings::wit_future::new(|| Ok(()));
    let (body, _trailers) = Request::consume_body(request, res_rx);
    let data = body.collect().await;
    drop(res_tx);
    data
}

/// Build a response with borrowed header pairs.
pub(crate) fn respond(status: u16, headers: &[(&str, &str)], body: Vec<u8>) -> Response {
    let fields = Fields::new();
    for &(name, value) in headers {
        let _ = fields.append(name, value.as_bytes());
    }
    finish_response(status, fields, body)
}

/// Build a response with owned header pairs (used where header values are
/// computed `String`s).
pub(crate) fn respond_owned(
    status: u16,
    headers: Vec<(String, String)>,
    body: Vec<u8>,
) -> Response {
    let fields = Fields::new();
    for (name, value) in &headers {
        let _ = fields.append(name, value.as_bytes());
    }
    finish_response(status, fields, body)
}

fn finish_response(status: u16, headers: Fields, body: Vec<u8>) -> Response {
    let (mut tx, rx) = bindings::wit_stream::new();
    let (trailers_tx, trailers_rx) = bindings::wit_future::new(|| Ok(None));
    wit_bindgen::spawn_local(async move {
        if !body.is_empty() {
            tx.write_all(body).await;
        }
        drop(tx);
        let _ = trailers_tx.write(Ok(None)).await;
    });
    let (response, _result) = Response::new(headers, Some(rx), trailers_rx);
    let _ = response.set_status_code(status);
    response
}

/// Build a response whose body is forwarded from an existing byte stream (e.g.
/// a blobstore `get-data` reader), so the payload is never buffered in the guest.
pub(crate) fn stream_response(
    status: u16,
    headers: Vec<(String, String)>,
    body: wit_bindgen::StreamReader<u8>,
) -> Response {
    let fields = Fields::new();
    for (name, value) in &headers {
        let _ = fields.append(name, value.as_bytes());
    }
    let (trailers_tx, trailers_rx) = bindings::wit_future::new(|| Ok(None));
    wit_bindgen::spawn_local(async move {
        let _ = trailers_tx.write(Ok(None)).await;
    });
    let (response, _result) = Response::new(fields, Some(body), trailers_rx);
    let _ = response.set_status_code(status);
    response
}

pub(crate) fn error_response(status: u16, code: &str, message: &str) -> Response {
    let body = serde_json::json!({
        "errors": [{ "code": code, "message": message }]
    })
    .to_string();
    respond(
        status,
        &[("content-type", "application/json")],
        body.into_bytes(),
    )
}

pub(crate) fn method_not_allowed() -> Response {
    error_response(405, "UNSUPPORTED", "method not allowed for this route")
}

//! Object-key naming scheme. Everything the registry persists lives as an object
//! in a single blobstore container, keyed by repository name.

/// Digests carry a `:` separator (`sha256:<hex>`) which is not portable across
/// blobstore backends (e.g. NATS object store keys), so it is sanitized.
fn sanitize(reference: &str) -> String {
    reference.replace(':', "_")
}

pub(crate) fn blob_key(name: &str, digest: &str) -> String {
    format!("{name}/blobs/{}", sanitize(digest))
}

pub(crate) fn manifest_key(name: &str, digest: &str) -> String {
    format!("{name}/manifests/{}", sanitize(digest))
}

pub(crate) fn media_type_key(manifest_key: &str) -> String {
    format!("{manifest_key}.mediatype")
}

pub(crate) fn tag_key(name: &str, tag: &str) -> String {
    format!("{name}/tags/{tag}")
}

pub(crate) fn upload_key(name: &str, session: &str) -> String {
    format!("{name}/uploads/{session}")
}

pub(crate) fn referrer_prefix(name: &str, subject: &str) -> String {
    format!("{name}/referrers/{}", sanitize(subject))
}

pub(crate) fn referrer_key(name: &str, subject: &str, manifest_digest: &str) -> String {
    format!(
        "{}/{}",
        referrer_prefix(name, subject),
        sanitize(manifest_digest)
    )
}

//! An OCI Distribution Spec (v2) registry implemented as a WebAssembly component,
//! backed by the async, native-stream `wasmcloud:blobstore@0.1.0` interface.
//!
//! The component is wasip3: it exports `wasi:http/handler@0.3.0` and stores every
//! blob, manifest, and tag as a blobstore object. Object bodies move as native
//! component-model `stream<u8>` values (no `wasi:io`), and every blobstore call is
//! `async`.
//!
//! | Operation          | Method | Path                                          |
//! | ------------------ | ------ | --------------------------------------------- |
//! | API version check  | GET    | `/v2/`                                         |
//! | Initiate upload    | POST   | `/v2/<name>/blobs/uploads/`                    |
//! | Cross-repo mount   | POST   | `/v2/<name>/blobs/uploads/?mount=&from=`      |
//! | Upload a chunk     | PATCH  | `/v2/<name>/blobs/uploads/<session>`          |
//! | Complete upload    | PUT    | `/v2/<name>/blobs/uploads/<session>?digest=`  |
//! | Pull a blob        | GET    | `/v2/<name>/blobs/<digest>`                    |
//! | Check a blob       | HEAD   | `/v2/<name>/blobs/<digest>`                    |
//! | Delete a blob      | DELETE | `/v2/<name>/blobs/<digest>`                    |
//! | Push a manifest    | PUT    | `/v2/<name>/manifests/<reference>`            |
//! | Pull a manifest    | GET    | `/v2/<name>/manifests/<reference>`            |
//! | Check a manifest   | HEAD   | `/v2/<name>/manifests/<reference>`            |
//! | Delete a manifest  | DELETE | `/v2/<name>/manifests/<reference>`            |
//! | List tags          | GET    | `/v2/<name>/tags/list`                         |
//! | List referrers     | GET    | `/v2/<name>/referrers/<digest>`               |
//!
//! The registry logic is split by functionality: [`route`] (URL parsing),
//! [`storage`] (blobstore access), [`keys`] (object-key naming), [`http`]
//! (response building), [`util`] (digests/queries), and one module per resource:
//! [`blobs`], [`manifests`], [`tags`], [`referrers`], [`uploads`].

mod bindings {
    wit_bindgen::generate!({
        world: "oci-registry",
        path: "wit",
        generate_all,
    });
}

mod auth;
mod blobs;
mod http;
mod keys;
mod manifests;
mod referrers;
mod route;
mod storage;
mod tags;
mod uploads;
mod util;

use bindings::exports::wasi::http::handler::Guest as Handler;

// Generated types shared across the modules.
use bindings::wasi::http::types::ErrorCode;
pub(crate) use bindings::wasi::http::types::{Fields, Method, Request, Response};
pub(crate) use bindings::wasmcloud::blobstore::container::Container;

use crate::blobs::{handle_blob, mount_blob, stream_and_finalize};
use crate::http::{error_response, header_str, method_not_allowed, read_request_body, respond};
use crate::keys::upload_key;
use crate::manifests::handle_manifest;
use crate::referrers::handle_referrers;
use crate::route::Route;
use crate::storage::{delete_object, ensure_container, read_object};
use crate::tags::handle_tags_list;
use crate::uploads::{begin_upload_session, handle_upload};
use crate::util::query_param;

struct Component;

impl Handler for Component {
    async fn handle(request: Request) -> Result<Response, ErrorCode> {
        // OCI-level outcomes (404/400/etc.) are normal responses; only an
        // unexpected backend failure bubbles up as a 500.
        Ok(match dispatch(request).await {
            Ok(response) => response,
            Err(message) => error_response(500, "INTERNAL_ERROR", &message),
        })
    }
}

async fn dispatch(request: Request) -> Result<Response, String> {
    let method = request.get_method();
    let path_and_query = request.get_path_with_query().unwrap_or_default();
    let (raw_path, query) = path_and_query
        .split_once('?')
        .unwrap_or((path_and_query.as_str(), ""));
    let path = raw_path.trim_matches('/').to_string();
    let query = query.to_string();

    let headers = request.get_headers();

    // Authenticate before anything else — including the `/v2/` version probe,
    // which is where an OCI client discovers the registry requires credentials.
    if let Some(challenge) = auth::require_basic(&headers).await {
        return Ok(challenge);
    }

    let content_type = header_str(&headers, "content-type");
    let content_range = header_str(&headers, "content-range");

    // `GET /v2/` is the base API version check used by clients to probe support.
    if path == "v2" {
        return Ok(respond(
            200,
            &[
                ("docker-distribution-api-version", "registry/2.0"),
                ("content-type", "application/json"),
            ],
            b"{}".to_vec(),
        ));
    }

    let Some(spec) = path.strip_prefix("v2/") else {
        return Ok(error_response(
            404,
            "UNSUPPORTED",
            "only the /v2/ registry API is supported",
        ));
    };

    let container = ensure_container().await?;
    let route = Route::parse(spec);

    // Streaming upload fast-paths: pipe the request body straight into the
    // blobstore while hashing, instead of buffering the whole blob. Monolithic
    // uploads (empty session) stream end-to-end; a PUT that finalizes prior
    // PATCH chunks streams those buffered bytes first.
    if let Some(Route::UploadInit { name }) = route
        && matches!(method, Method::Post)
    {
        // Cross-repository blob mount: `?mount=<digest>&from=<source-repo>`.
        if let Some(mount_digest) = query_param(&query, "mount") {
            return match query_param(&query, "from") {
                Some(from) => mount_blob(&container, name, &mount_digest, &from).await,
                // `mount` without `from`: no automatic content discovery, so fall
                // back to a normal upload session.
                None => begin_upload_session(&container, name).await,
            };
        }
        return match query_param(&query, "digest") {
            Some(expected) => {
                stream_and_finalize(&container, name, &expected, Vec::new(), request).await
            }
            None => begin_upload_session(&container, name).await,
        };
    }
    if let Some(Route::Upload { name, session }) = route
        && matches!(method, Method::Put)
        && let Some(expected) = query_param(&query, "digest")
    {
        let key = upload_key(name, session);
        let Some(prior) = read_object(&container, &key).await? else {
            return Ok(error_response(
                404,
                "BLOB_UPLOAD_UNKNOWN",
                "upload session unknown",
            ));
        };
        let response = stream_and_finalize(&container, name, &expected, prior, request).await?;
        delete_object(&container, &key).await?;
        return Ok(response);
    }

    // Remaining body-bearing methods (manifests, PATCH chunks) are buffered.
    let body = if matches!(method, Method::Put | Method::Post | Method::Patch) {
        read_request_body(request).await
    } else {
        Vec::new()
    };

    match route {
        Some(Route::TagsList { name }) => handle_tags_list(&container, name, &query).await,
        Some(Route::Referrers { name, digest }) => {
            handle_referrers(&container, name, digest, &query).await
        }
        Some(Route::Manifest { name, reference }) => {
            handle_manifest(
                &container,
                &method,
                name,
                reference,
                content_type.as_deref(),
                &body,
            )
            .await
        }
        // POST is handled by the streaming fast-path above; anything else here
        // is an unsupported method on the uploads endpoint.
        Some(Route::UploadInit { .. }) => Ok(method_not_allowed()),
        Some(Route::Upload { name, session }) => {
            handle_upload(
                &container,
                &method,
                name,
                session,
                content_range.as_deref(),
                &body,
            )
            .await
        }
        Some(Route::Blob { name, digest }) => handle_blob(&container, &method, name, digest).await,
        None => Ok(error_response(
            404,
            "NAME_UNKNOWN",
            "unrecognized registry route",
        )),
    }
}

bindings::export!(Component with_types_in bindings);

//! Manifest push/pull/delete and the `subject`/referrer metadata extracted on push.

use crate::http::{error_response, method_not_allowed, respond, respond_owned};
use crate::keys::{manifest_key, media_type_key, referrer_key, tag_key};
use crate::storage::{delete_object, has_object, read_object, write_object};
use crate::util::{is_digest, sha256_digest};
use crate::{Container, Method, Response};

/// Media type returned for manifests when no stored content type is available.
const DEFAULT_MANIFEST_MEDIA_TYPE: &str = "application/vnd.oci.image.manifest.v1+json";

pub(crate) async fn handle_manifest(
    container: &Container,
    method: &Method,
    name: &str,
    reference: &str,
    content_type: Option<&str>,
    body: &[u8],
) -> Result<Response, String> {
    match method {
        Method::Put => {
            let digest = sha256_digest(body);
            let media_type = content_type
                .unwrap_or(DEFAULT_MANIFEST_MEDIA_TYPE)
                .to_string();

            let content_key = manifest_key(name, &digest);
            write_object(container, &content_key, body.to_vec()).await?;
            write_object(
                container,
                &media_type_key(&content_key),
                media_type.clone().into_bytes(),
            )
            .await?;

            // A tag reference also gets a pointer object mapping tag -> digest.
            if !is_digest(reference) {
                write_object(
                    container,
                    &tag_key(name, reference),
                    digest.clone().into_bytes(),
                )
                .await?;
            }

            // If the manifest declares a `subject`, index a referrer descriptor
            // under that subject's digest so it shows up in the referrers API.
            let meta = ManifestMetadata::parse(body);
            let mut headers = vec![
                (
                    "location".to_string(),
                    format!("/v2/{name}/manifests/{digest}"),
                ),
                ("docker-content-digest".to_string(), digest.clone()),
            ];
            if let Some(subject) = &meta.subject {
                let descriptor = meta.descriptor(&digest, &media_type, body.len() as u64);
                write_object(
                    container,
                    &referrer_key(name, subject, &digest),
                    descriptor.to_string().into_bytes(),
                )
                .await?;
                headers.push(("oci-subject".to_string(), subject.clone()));
            }

            Ok(respond_owned(201, headers, Vec::new()))
        }
        Method::Get | Method::Head => {
            let Some(digest) = resolve_reference(container, name, reference).await? else {
                return Ok(error_response(404, "MANIFEST_UNKNOWN", "manifest unknown"));
            };
            let content_key = manifest_key(name, &digest);
            let Some(data) = read_object(container, &content_key).await? else {
                return Ok(error_response(404, "MANIFEST_UNKNOWN", "manifest unknown"));
            };
            let media_type = read_object(container, &media_type_key(&content_key))
                .await?
                .and_then(|b| String::from_utf8(b).ok())
                .unwrap_or_else(|| DEFAULT_MANIFEST_MEDIA_TYPE.to_string());

            if matches!(method, Method::Head) {
                return Ok(respond_owned(
                    200,
                    vec![
                        ("content-type".to_string(), media_type),
                        ("docker-content-digest".to_string(), digest),
                    ],
                    Vec::new(),
                ));
            }
            let len = data.len().to_string();
            Ok(respond_owned(
                200,
                vec![
                    ("content-type".to_string(), media_type),
                    ("docker-content-digest".to_string(), digest),
                    ("content-length".to_string(), len),
                ],
                data,
            ))
        }
        Method::Delete => {
            // Deleting by digest removes the manifest content (any tags still
            // pointing at it become dangling). Deleting by tag only removes that
            // tag, leaving the shared content and other tags intact.
            if is_digest(reference) {
                let content_key = manifest_key(name, reference);
                let Some(data) = read_object(container, &content_key).await? else {
                    return Ok(error_response(404, "MANIFEST_UNKNOWN", "manifest unknown"));
                };
                // Drop the referrer entry this manifest may have registered.
                if let Some(subject) = ManifestMetadata::parse(&data).subject {
                    delete_object(container, &referrer_key(name, &subject, reference)).await?;
                }
                delete_object(container, &content_key).await?;
                delete_object(container, &media_type_key(&content_key)).await?;
            } else {
                let tag = tag_key(name, reference);
                if !has_object(container, &tag).await? {
                    return Ok(error_response(404, "MANIFEST_UNKNOWN", "manifest unknown"));
                }
                delete_object(container, &tag).await?;
            }
            Ok(respond(202, &[], Vec::new()))
        }
        _ => Ok(method_not_allowed()),
    }
}

/// Resolve a manifest reference (either a digest or a tag) to a concrete digest.
async fn resolve_reference(
    container: &Container,
    name: &str,
    reference: &str,
) -> Result<Option<String>, String> {
    if is_digest(reference) {
        return Ok(Some(reference.to_string()));
    }
    match read_object(container, &tag_key(name, reference)).await? {
        Some(bytes) => Ok(String::from_utf8(bytes).ok()),
        None => Ok(None),
    }
}

/// The subset of a manifest relevant to the referrers API.
struct ManifestMetadata {
    /// Digest from the manifest's `subject` descriptor, if any.
    subject: Option<String>,
    /// The manifest's `artifactType`, falling back to `config.mediaType`.
    artifact_type: Option<String>,
    /// The manifest's top-level `annotations`, propagated into the descriptor.
    annotations: Option<serde_json::Value>,
}

impl ManifestMetadata {
    fn parse(data: &[u8]) -> Self {
        let value: serde_json::Value =
            serde_json::from_slice(data).unwrap_or(serde_json::Value::Null);
        let subject = value
            .get("subject")
            .and_then(|s| s.get("digest"))
            .and_then(|d| d.as_str())
            .map(str::to_string);
        let artifact_type = value
            .get("artifactType")
            .and_then(|v| v.as_str())
            .or_else(|| {
                value
                    .get("config")
                    .and_then(|c| c.get("mediaType"))
                    .and_then(|v| v.as_str())
            })
            .map(str::to_string);
        let annotations = value.get("annotations").cloned();
        Self {
            subject,
            artifact_type,
            annotations,
        }
    }

    /// Build the OCI descriptor recorded in the referrers index for this manifest.
    fn descriptor(&self, digest: &str, media_type: &str, size: u64) -> serde_json::Value {
        let mut map = serde_json::Map::new();
        map.insert("mediaType".into(), media_type.into());
        map.insert("digest".into(), digest.into());
        map.insert("size".into(), size.into());
        if let Some(artifact_type) = &self.artifact_type {
            map.insert("artifactType".into(), artifact_type.clone().into());
        }
        if let Some(annotations) = &self.annotations {
            map.insert("annotations".into(), annotations.clone());
        }
        serde_json::Value::Object(map)
    }
}

//! The referrers API: list the manifests that declare a given digest as their
//! `subject`, as an OCI image index.

use crate::http::respond_owned;
use crate::keys::referrer_prefix;
use crate::storage::{list_keys, read_object};
use crate::util::query_param;
use crate::{Container, Response};

/// Media type of the image index returned by the referrers API.
const OCI_IMAGE_INDEX_MEDIA_TYPE: &str = "application/vnd.oci.image.index.v1+json";

pub(crate) async fn handle_referrers(
    container: &Container,
    name: &str,
    subject: &str,
    query: &str,
) -> Result<Response, String> {
    let prefix = format!("{}/", referrer_prefix(name, subject));
    let filter = query_param(query, "artifactType");

    let mut manifests = Vec::new();
    for key in list_keys(container).await? {
        if !key.starts_with(&prefix) {
            continue;
        }
        let Some(bytes) = read_object(container, &key).await? else {
            continue;
        };
        let Ok(descriptor) = serde_json::from_slice::<serde_json::Value>(&bytes) else {
            continue;
        };
        if let Some(want) = &filter {
            let got = descriptor.get("artifactType").and_then(|v| v.as_str());
            if got != Some(want.as_str()) {
                continue;
            }
        }
        manifests.push(descriptor);
    }

    let index = serde_json::json!({
        "schemaVersion": 2,
        "mediaType": OCI_IMAGE_INDEX_MEDIA_TYPE,
        "manifests": manifests,
    });

    let mut headers = vec![(
        "content-type".to_string(),
        OCI_IMAGE_INDEX_MEDIA_TYPE.to_string(),
    )];
    // Signal that the artifactType filter was honored (per the referrers spec).
    if filter.is_some() {
        headers.push((
            "oci-filters-applied".to_string(),
            "artifactType".to_string(),
        ));
    }
    Ok(respond_owned(200, headers, index.to_string().into_bytes()))
}

//! Parsing of the OCI registry URL space into typed routes.

/// A parsed OCI registry route. `name` is the (possibly multi-segment) repository
/// name, e.g. `library/nginx`.
#[derive(Clone, Copy)]
pub(crate) enum Route<'a> {
    TagsList { name: &'a str },
    Referrers { name: &'a str, digest: &'a str },
    Manifest { name: &'a str, reference: &'a str },
    UploadInit { name: &'a str },
    Upload { name: &'a str, session: &'a str },
    Blob { name: &'a str, digest: &'a str },
}

impl<'a> Route<'a> {
    /// Parse the portion of the path after the `v2/` prefix. Markers are matched
    /// from the right so repository names that contain reserved words still parse,
    /// and the more specific `blobs/uploads` cases are checked before `blobs`.
    pub(crate) fn parse(spec: &'a str) -> Option<Route<'a>> {
        if let Some(name) = spec.strip_suffix("/tags/list") {
            return Some(Route::TagsList { name });
        }
        if let Some(idx) = spec.rfind("/referrers/") {
            let name = spec.get(..idx)?;
            let digest = spec.get(idx + "/referrers/".len()..)?;
            if !name.is_empty() && !digest.is_empty() {
                return Some(Route::Referrers { name, digest });
            }
        }
        if let Some(idx) = spec.rfind("/manifests/") {
            let name = spec.get(..idx)?;
            let reference = spec.get(idx + "/manifests/".len()..)?;
            if !name.is_empty() && !reference.is_empty() {
                return Some(Route::Manifest { name, reference });
            }
        }
        if let Some(idx) = spec.rfind("/blobs/uploads/") {
            let name = spec.get(..idx)?;
            let session = spec.get(idx + "/blobs/uploads/".len()..)?;
            if !name.is_empty() && !session.is_empty() {
                return Some(Route::Upload { name, session });
            }
        }
        if let Some(name) = spec.strip_suffix("/blobs/uploads")
            && !name.is_empty()
        {
            return Some(Route::UploadInit { name });
        }
        if let Some(idx) = spec.rfind("/blobs/") {
            let name = spec.get(..idx)?;
            let digest = spec.get(idx + "/blobs/".len()..)?;
            if !name.is_empty() && !digest.is_empty() {
                return Some(Route::Blob { name, digest });
            }
        }
        None
    }
}

//! The storage layer over async `wasmcloud:blobstore`. Everything the registry
//! persists lives as an object in a single container, keyed by repository name
//! (see [`crate::keys`] for the naming scheme).

use crate::Container;
use crate::bindings;
use crate::bindings::wasmcloud::blobstore::blobstore;
use crate::bindings::wasmcloud::blobstore::types::{Error as BlobError, ObjectId};

/// All registry objects live in a single blobstore container, keyed by
/// repository name (e.g. `library/nginx/blobs/sha256_<hex>`).
const CONTAINER_NAME: &str = "oci-registry";

/// Fetch (or create) the registry container.
pub(crate) async fn ensure_container() -> Result<Container, String> {
    if blobstore::container_exists(CONTAINER_NAME.to_string())
        .await
        .map_err(blob_err)?
    {
        return blobstore::get_container(CONTAINER_NAME.to_string())
            .await
            .map_err(blob_err);
    }
    match blobstore::create_container(CONTAINER_NAME.to_string()).await {
        Ok(container) => Ok(container),
        // A concurrent request created it between the check and here (e.g. oras
        // uploads a manifest's blobs in parallel); fetch the existing one.
        Err(BlobError::ContainerAlreadyExists) => {
            blobstore::get_container(CONTAINER_NAME.to_string())
                .await
                .map_err(blob_err)
        }
        Err(e) => Err(blob_err(e)),
    }
}

pub(crate) async fn object_size(container: &Container, key: &str) -> Result<u64, String> {
    Ok(container
        .object_info(key.to_string())
        .await
        .map_err(blob_err)?
        .size)
}

pub(crate) async fn has_object(container: &Container, key: &str) -> Result<bool, String> {
    container
        .has_object(key.to_string())
        .await
        .map_err(blob_err)
}

pub(crate) async fn delete_object(container: &Container, key: &str) -> Result<(), String> {
    container
        .delete_object(key.to_string())
        .await
        .map_err(blob_err)
}

pub(crate) async fn list_keys(container: &Container) -> Result<Vec<String>, String> {
    let stream = container.list_objects().await.map_err(blob_err)?;
    Ok(stream.collect().await)
}

/// Read an entire object into memory. Returns `None` if the object is absent.
pub(crate) async fn read_object(
    container: &Container,
    key: &str,
) -> Result<Option<Vec<u8>>, String> {
    if !container
        .has_object(key.to_string())
        .await
        .map_err(blob_err)?
    {
        return Ok(None);
    }
    let size = container
        .object_info(key.to_string())
        .await
        .map_err(blob_err)?
        .size;
    if size == 0 {
        return Ok(Some(Vec::new()));
    }
    // Offsets are inclusive, so the last byte is at `size - 1`.
    let stream = container
        .get_data(key.to_string(), 0, size - 1)
        .await
        .map_err(blob_err)?;
    Ok(Some(stream.collect().await))
}

/// Open a blobstore object as a byte stream for forwarding into a response body
/// (a 0-byte object yields an already-closed empty stream).
pub(crate) async fn open_object_stream(
    container: &Container,
    key: &str,
    size: u64,
) -> Result<wit_bindgen::StreamReader<u8>, String> {
    if size == 0 {
        let (writer, reader) = bindings::wit_stream::new();
        drop(writer);
        return Ok(reader);
    }
    // Offsets are inclusive, so the last byte is at `size - 1`.
    container
        .get_data(key.to_string(), 0, size - 1)
        .await
        .map_err(blob_err)
}

/// Create or replace an object, streaming `data` to the blobstore.
pub(crate) async fn write_object(
    container: &Container,
    key: &str,
    data: Vec<u8>,
) -> Result<(), String> {
    let (mut tx, rx) = bindings::wit_stream::new();
    wit_bindgen::spawn_local(async move {
        if !data.is_empty() {
            tx.write_all(data).await;
        }
        drop(tx);
    });
    container
        .write_data(key.to_string(), rx)
        .await
        .map_err(blob_err)
}

/// Copy an object within the registry container (used by cross-repo mount).
pub(crate) async fn copy_object(source: &str, dest: &str) -> Result<(), String> {
    blobstore::copy_object(object_id(source), object_id(dest))
        .await
        .map_err(blob_err)
}

/// An `object-id` in the single registry container.
fn object_id(object: &str) -> ObjectId {
    ObjectId {
        container: CONTAINER_NAME.to_string(),
        object: object.to_string(),
    }
}

pub(crate) fn blob_err(error: BlobError) -> String {
    match error {
        BlobError::NoSuchContainer => "no such container".to_string(),
        BlobError::ContainerAlreadyExists => "container already exists".to_string(),
        BlobError::NoSuchObject => "no such object".to_string(),
        BlobError::AccessDenied => "access denied".to_string(),
        BlobError::Timeout => "blobstore timeout".to_string(),
        BlobError::StoreUnavailable => "blobstore unavailable".to_string(),
        BlobError::QuotaExceeded => "blobstore quota exceeded".to_string(),
        BlobError::Other(message) => message,
    }
}

//! Tag listing with `n`/`last` pagination.

use crate::http::respond_owned;
use crate::storage::list_keys;
use crate::util::query_param;
use crate::{Container, Response};

pub(crate) async fn handle_tags_list(
    container: &Container,
    name: &str,
    query: &str,
) -> Result<Response, String> {
    let prefix = format!("{name}/tags/");
    let mut tags: Vec<String> = list_keys(container)
        .await?
        .into_iter()
        .filter_map(|key| key.strip_prefix(&prefix).map(str::to_string))
        .collect();
    tags.sort();

    // Pagination: `last` resumes after a given tag, `n` limits the page size.
    if let Some(last) = query_param(query, "last") {
        tags.retain(|tag| tag.as_str() > last.as_str());
    }
    let limit = query_param(query, "n").and_then(|n| n.parse::<usize>().ok());
    let mut next_link = None;
    if let Some(limit) = limit
        && tags.len() > limit
    {
        tags.truncate(limit);
        if let Some(last) = tags.last() {
            next_link = Some(format!(
                "</v2/{name}/tags/list?n={limit}&last={last}>; rel=\"next\""
            ));
        }
    }

    let body = serde_json::json!({ "name": name, "tags": tags }).to_string();
    let mut headers = vec![("content-type".to_string(), "application/json".to_string())];
    if let Some(link) = next_link {
        headers.push(("link".to_string(), link));
    }
    Ok(respond_owned(200, headers, body.into_bytes()))
}

//! Blob upload sessions: initiation, chunked `PATCH` appends, and status.
//!
//! Monolithic and finalizing (`PUT ?digest=`) uploads are handled by the
//! streaming fast-path in `crate::dispatch` (see [`crate::blobs`]).

use crate::http::{error_response, method_not_allowed, respond_owned};
use crate::keys::upload_key;
use crate::storage::{has_object, object_size, read_object, write_object};
use crate::util::{new_session_id, range_header, range_start};
use crate::{Container, Method, Response};

/// Begin a resumable upload session backed by an (initially empty) object.
pub(crate) async fn begin_upload_session(
    container: &Container,
    name: &str,
) -> Result<Response, String> {
    let session = new_session_id();
    write_object(container, &upload_key(name, &session), Vec::new()).await?;

    Ok(respond_owned(
        202,
        vec![
            (
                "location".to_string(),
                format!("/v2/{name}/blobs/uploads/{session}"),
            ),
            ("docker-upload-uuid".to_string(), session),
            ("range".to_string(), "0-0".to_string()),
        ],
        Vec::new(),
    ))
}

pub(crate) async fn handle_upload(
    container: &Container,
    method: &Method,
    name: &str,
    session: &str,
    content_range: Option<&str>,
    body: &[u8],
) -> Result<Response, String> {
    let key = upload_key(name, session);

    match method {
        // Status of an in-progress upload.
        Method::Get => {
            if !has_object(container, &key).await? {
                return Ok(error_response(
                    404,
                    "BLOB_UPLOAD_UNKNOWN",
                    "upload session unknown",
                ));
            }
            let size = object_size(container, &key).await?;
            Ok(respond_owned(
                204,
                vec![
                    (
                        "location".to_string(),
                        format!("/v2/{name}/blobs/uploads/{session}"),
                    ),
                    ("docker-upload-uuid".to_string(), session.to_string()),
                    ("range".to_string(), range_header(size)),
                ],
                Vec::new(),
            ))
        }
        // Append a chunk to the session.
        Method::Patch => {
            let Some(mut buf) = read_object(container, &key).await? else {
                return Ok(error_response(
                    404,
                    "BLOB_UPLOAD_UNKNOWN",
                    "upload session unknown",
                ));
            };
            // When a Content-Range is supplied, it must start exactly where the
            // session currently ends; out-of-order or replayed chunks are
            // rejected with 416 (per the chunked-upload spec).
            if let Some(range) = content_range {
                let Some(start) = range_start(range) else {
                    return Ok(error_response(
                        400,
                        "SIZE_INVALID",
                        "malformed Content-Range header",
                    ));
                };
                if start != buf.len() as u64 {
                    return Ok(respond_owned(
                        416,
                        vec![
                            (
                                "location".to_string(),
                                format!("/v2/{name}/blobs/uploads/{session}"),
                            ),
                            ("docker-upload-uuid".to_string(), session.to_string()),
                            ("range".to_string(), range_header(buf.len() as u64)),
                        ],
                        Vec::new(),
                    ));
                }
            }
            buf.extend_from_slice(body);
            let new_len = buf.len() as u64;
            write_object(container, &key, buf).await?;

            Ok(respond_owned(
                202,
                vec![
                    (
                        "location".to_string(),
                        format!("/v2/{name}/blobs/uploads/{session}"),
                    ),
                    ("docker-upload-uuid".to_string(), session.to_string()),
                    ("range".to_string(), range_header(new_len)),
                ],
                Vec::new(),
            ))
        }
        // A PUT that finalizes an upload carries `?digest=` and is handled by the
        // streaming fast-path in `dispatch`; reaching here means it was missing.
        Method::Put => Ok(error_response(
            400,
            "DIGEST_INVALID",
            "digest query parameter is required to complete an upload",
        )),
        _ => Ok(method_not_allowed()),
    }
}

//! Small pure helpers: digests, session ids, ranges, and query parsing.

use crate::bindings;
use sha2::{Digest, Sha256};

/// A reference is a digest (rather than a tag) when it carries an `algo:hex`
/// separator; tags cannot contain `:`.
pub(crate) fn is_digest(reference: &str) -> bool {
    reference.contains(':')
}

pub(crate) fn sha256_digest(data: &[u8]) -> String {
    let mut hasher = Sha256::new();
    hasher.update(data);
    format!("sha256:{}", hex::encode(hasher.finalize()))
}

pub(crate) fn new_session_id() -> String {
    let bytes = bindings::wasi::random::random::get_random_bytes(16);
    hex::encode(bytes)
}

pub(crate) fn range_header(len: u64) -> String {
    if len == 0 {
        "0-0".to_string()
    } else {
        format!("0-{}", len - 1)
    }
}

/// Parse the inclusive start offset from a `Content-Range: <start>-<end>` header.
pub(crate) fn range_start(range: &str) -> Option<u64> {
    let range = range.trim();
    let range = range.strip_prefix("bytes ").unwrap_or(range);
    let (start, _) = range.split_once('-')?;
    start.trim().parse::<u64>().ok()
}

/// Extract and percent-decode a query parameter value.
pub(crate) fn query_param(query: &str, key: &str) -> Option<String> {
    query.split('&').find_map(|pair| {
        let (k, v) = pair.split_once('=')?;
        (k == key).then(|| percent_decode(v))
    })
}

/// Decode `%XX` escapes in a string. Other bytes (including `+`) are left as-is,
/// which keeps media types such as `application/vnd...v1+json` intact.
fn percent_decode(input: &str) -> String {
    let bytes = input.as_bytes();
    let mut out = Vec::with_capacity(bytes.len());
    let mut i = 0;
    while let Some(&byte) = bytes.get(i) {
        if byte == b'%' {
            let high = bytes.get(i + 1).copied().and_then(hex_value);
            let low = bytes.get(i + 2).copied().and_then(hex_value);
            if let (Some(high), Some(low)) = (high, low) {
                out.push(high * 16 + low);
                i += 3;
                continue;
            }
        }
        out.push(byte);
        i += 1;
    }
    String::from_utf8_lossy(&out).into_owned()
}

fn hex_value(byte: u8) -> Option<u8> {
    match byte {
        b'0'..=b'9' => Some(byte - b'0'),
        b'a'..=b'f' => Some(byte - b'a' + 10),
        b'A'..=b'F' => Some(byte - b'A' + 10),
        _ => None,
    }
}

//! Blobstore helper for stashing the fetched response body.

use anyhow::{Context, Result, anyhow};

use crate::bindings::wasi::blobstore::{
    blobstore::{Container, create_container, get_container},
    types::OutgoingValue,
};

pub(crate) const CONTAINER_NAME: &str = "http-responses";
pub(crate) const OBJECT_KEY: &str = "example-com-response";

pub(crate) fn store_response_in_blobstore(body: &[u8]) -> Result<()> {
    let container = open_or_create_container(CONTAINER_NAME)?;

    let outgoing = OutgoingValue::new_outgoing_value();
    let stream = outgoing
        .outgoing_value_write_body()
        .map_err(|()| anyhow!("failed to open blobstore output stream"))?;
    // `blocking-write-and-flush` accepts at most 4096 bytes per call and traps
    // on more, so chunk the body. Upstream responses in a workload-to-workload
    // chain are easily larger than a single permit.
    for chunk in body.chunks(4096) {
        stream
            .blocking_write_and_flush(chunk)
            .context("failed to write blob bytes")?;
    }
    drop(stream);

    container
        .write_data(OBJECT_KEY, &outgoing)
        .map_err(|e| anyhow!("failed to write blob {OBJECT_KEY}: {e}"))?;
    OutgoingValue::finish(outgoing).map_err(|e| anyhow!("failed to finish blob value: {e}"))?;
    Ok(())
}

/// Try to open the container; if that fails, log the original error and
/// attempt to create it. Logging the original keeps an auth/transport failure
/// visible instead of being silently masked by a subsequent create failure.
fn open_or_create_container(name: &str) -> Result<Container> {
    match get_container(name) {
        Ok(c) => Ok(c),
        Err(get_err) => {
            eprintln!(
                "blobstore get_container({name}) failed: {get_err}; attempting create_container"
            );
            create_container(name)
                .map_err(|e| anyhow!("failed to create blobstore container {name}: {e}"))
        }
    }
}

//! Per-request app config sourced from `wasi:config/store` (populated by
//! `workload.environment.{configFrom,secretFrom}` in `.wash/config.yaml`).

use std::collections::BTreeMap;
use std::sync::OnceLock;
use std::sync::atomic::{AtomicBool, Ordering};

use wstd::time::Duration;

use crate::bindings::wasi::config::store::get_all;
use crate::otel::{TraceFlags, otel_log};

const DEFAULT_OUTBOUND_HOST: &str = "example.com";
const DEFAULT_REQUEST_TIMEOUT_MS: u64 = 5_000;

/// OTLP endpoint to display in the demo UI. Matches the
/// `OTEL_EXPORTER_OTLP_ENDPOINT` value set by `.wash/config.yaml` and the
/// .NET Aspire dashboard's gRPC port. Guest components can't currently read
/// process env back out, so this is a static label rather than a live read.
const DISPLAY_OTLP_ENDPOINT: &str = "http://localhost:18889";

pub(crate) fn otlp_endpoint() -> &'static str {
    DISPLAY_OTLP_ENDPOINT
}

pub(crate) struct AppConfig {
    pub(crate) outbound_url: String,
    pub(crate) request_timeout: Duration,
    pub(crate) upstream_api_token: Option<String>,
}

static APP_CONFIG: OnceLock<AppConfig> = OnceLock::new();

pub(crate) fn app_config() -> &'static AppConfig {
    APP_CONFIG.get_or_init(build_app_config)
}

fn build_app_config() -> AppConfig {
    let mut entries: BTreeMap<String, String> = BTreeMap::new();
    if let Ok(config) = get_all() {
        for (k, v) in config {
            entries.insert(k, v);
        }
    }
    // `OUTBOUND_URL`, when set, is used verbatim. This lets a workload point at
    // a sibling workload over `http://host:port/` (see the multi-workload
    // roll-up demo in the README), where the bare-host + implicit-`https`
    // shape of `OUTBOUND_HOST` doesn't fit. Otherwise fall back to
    // `https://{OUTBOUND_HOST}/`.
    let outbound_url = entries.get("OUTBOUND_URL").cloned().unwrap_or_else(|| {
        let outbound_host = entries
            .get("OUTBOUND_HOST")
            .map(String::as_str)
            .unwrap_or(DEFAULT_OUTBOUND_HOST);
        format!("https://{outbound_host}/")
    });
    let timeout_ms = entries
        .get("REQUEST_TIMEOUT_MS")
        .and_then(|s| s.parse::<u64>().ok())
        .unwrap_or(DEFAULT_REQUEST_TIMEOUT_MS);
    AppConfig {
        outbound_url,
        request_timeout: Duration::from_millis(timeout_ms),
        upstream_api_token: entries.get("UPSTREAM_API_TOKEN").cloned(),
    }
}

/// One-shot startup audit: emit a single OTel log line listing every
/// `wasi:config/store` key visible to the component. **Keys only**,
/// values are deliberately not included because secret values
/// (`workload.environment.secretFrom` entries) land in this same map.
///
/// Latch is set only on success, so a transient cold-start failure of
/// `wasi:config` does not permanently silence the audit log.
pub(crate) fn log_runtime_config(trace_id: &str, span_id: &str, flags: TraceFlags) {
    static LOGGED: AtomicBool = AtomicBool::new(false);
    if LOGGED.load(Ordering::Relaxed) {
        return;
    }
    let keys: Vec<String> = match get_all() {
        Ok(entries) => entries.into_iter().map(|(k, _)| k).collect(),
        Err(e) => {
            eprintln!("warning: failed to read wasi:config/store: {e:?}");
            return;
        }
    };
    otel_log(
        &format!("wasi:config keys: {}", keys.join(", ")),
        trace_id,
        span_id,
        flags,
    );
    LOGGED.store(true, Ordering::Relaxed);
}

//! Keyvalue helper for the request counter.

use anyhow::{Context, Result, anyhow};

use crate::bindings::wasi::keyvalue::{atomics::increment, store::open};

pub(crate) const COUNTER_KEY: &str = "request-count";

pub(crate) fn increment_counter() -> Result<u64> {
    let bucket = open("").map_err(|e| anyhow!("failed to open keyvalue bucket: {e:?}"))?;
    increment(&bucket, COUNTER_KEY, 1).context("failed to increment counter")
}

//! `OTel` config example.
//!
//! Handles an incoming HTTP request, fetches the configured upstream, stashes
//! the body in a blob, increments a request counter, and exports the whole
//! flow through `wasi:otel/{tracing,logs,metrics}`, including W3C trace
//! context propagation on the outbound call. The OTel `Resource` is built
//! from `wasi:config` (`otel.resource.*` keys).
//!
//! The reusable OTel scaffolding (cached resource/scope, [`otel::otel_log`],
//! [`otel::ActiveSpan`] RAII guard, and all `wasi:otel` bindings re-exports)
//! lives in [`mod@otel`]. Per-capability helpers live in their own modules
//! (`config`, `outbound`, `blobstore`, `keyvalue`, `metrics`, `ui`).

use anyhow::{Error, Result};
use wstd::http::{Body, Request, Response, StatusCode};

mod bindings {
    wit_bindgen::generate!({
        world: "otel-config",
        path: "wit",
        generate_all,
    });
}

mod blobstore;
mod config;
mod keyvalue;
mod metrics;
mod otel;
mod outbound;
mod ui;

use blobstore::{CONTAINER_NAME, OBJECT_KEY, store_response_in_blobstore};
use config::{app_config, log_runtime_config, otlp_endpoint};
use keyvalue::{COUNTER_KEY, increment_counter};
use metrics::export_metrics;
use otel::{
    ActiveSpan, Event, SpanKind, TraceFlags, kv_num, kv_str, new_trace_id, now, otel_log,
    outer_span_context,
};
use outbound::make_outgoing_request;

/// Everything the response renderer needs to draw the demo page.
struct Outcome {
    count: u64,
    response_len: usize,
    outbound_url: String,
    trace_id: String,
    request_span_id: String,
}

#[wstd::http_server]
async fn main(_request: Request<Body>) -> Result<Response<Body>, wstd::http::Error> {
    let (status, body) = match handle_request().await {
        Ok(outcome) => {
            let page = ui::render_page(&ui::PageData {
                count: outcome.count,
                response_len: outcome.response_len,
                outbound_url: &outcome.outbound_url,
                trace_id: &outcome.trace_id,
                span_id: &outcome.request_span_id,
                otlp_endpoint: otlp_endpoint(),
            });
            (StatusCode::OK, page)
        }
        Err(e) => {
            eprintln!("error processing request: {e:?}");
            (
                StatusCode::INTERNAL_SERVER_ERROR,
                ui::render_error(&format!("{e:#}")),
            )
        }
    };

    Response::builder()
        .status(status)
        .header("content-type", "text/html; charset=utf-8")
        .body(Body::from(body))
        .map_err(Into::into)
}

async fn handle_request() -> Result<Outcome> {
    // Continue the host-provided trace if there is one; otherwise root a fresh
    // trace. Inherit the upstream sampling decision so we don't override a
    // host that asked us not to record.
    let outer_ctx = outer_span_context();
    let (trace_id, flags, outer_parent_span_id) = if outer_ctx.trace_id.is_empty() {
        (new_trace_id(), TraceFlags::SAMPLED, String::new())
    } else {
        (outer_ctx.trace_id, outer_ctx.trace_flags, outer_ctx.span_id)
    };

    let request_span = ActiveSpan::start(
        &trace_id,
        flags,
        outer_parent_span_id,
        SpanKind::Server,
        "handle-request",
    );
    let request_span_id = request_span.span_id().to_owned();

    log_runtime_config(&trace_id, &request_span_id, flags);

    otel_log(
        "handling otel-config request",
        &trace_id,
        &request_span_id,
        flags,
    );

    match handle_request_steps(&trace_id, &request_span_id, flags).await {
        Ok((count, response_len, outbound_url)) => {
            // Parent SERVER span carries summary attributes + a completion event.
            request_span.finish_ok_with(
                vec![kv_num("request.count", count)],
                vec![Event {
                    name: "request.completed".into(),
                    time: now(),
                    attributes: vec![kv_num("response.bytes", response_len)],
                }],
            );

            otel_log(
                &format!("request complete, count: {count}"),
                &trace_id,
                &request_span_id,
                flags,
            );

            export_metrics(count, response_len, &outbound_url);
            Ok(Outcome {
                count,
                response_len,
                outbound_url,
                trace_id,
                request_span_id,
            })
        }
        Err(e) => {
            request_span.finish_err(format!("{e:#}"));
            Err(e)
        }
    }
}

/// Inner workhorse: runs the http → blob → keyvalue chain, marking each
/// child span as either `Ok` or `Err(message)` so the trace carries the real
/// cause instead of the generic "exited via early return" message.
async fn handle_request_steps(
    trace_id: &str,
    parent_span_id: &str,
    flags: TraceFlags,
) -> Result<(u64, usize, String)> {
    let outbound_url = app_config().outbound_url.clone();

    // Outgoing http child CLIENT span, traceparent injected on the wire.
    let http_span = ActiveSpan::start(
        trace_id,
        flags,
        parent_span_id,
        SpanKind::Client,
        "outgoing http",
    );
    let http_span_id = http_span.span_id().to_owned();
    let body_bytes = finish_span_with_result(
        http_span,
        make_outgoing_request(trace_id, &http_span_id, flags).await,
        |b| {
            vec![
                kv_str("http.request.method", "GET"),
                kv_str("url.full", &outbound_url),
                kv_num("http.response.body.size", b.len()),
            ]
        },
    )?;
    let response_len = body_bytes.len();

    otel_log(
        &format!("retrieved {response_len} bytes from {outbound_url}"),
        trace_id,
        parent_span_id,
        flags,
    );

    // Blobstore write — child CLIENT span.
    let blob_span = ActiveSpan::start(
        trace_id,
        flags,
        parent_span_id,
        SpanKind::Client,
        "blobstore write",
    );
    finish_span_with_result(blob_span, store_response_in_blobstore(&body_bytes), |()| {
        vec![
            kv_str("blobstore.container", CONTAINER_NAME),
            kv_str("blobstore.object", OBJECT_KEY),
            kv_num("blobstore.object.size", response_len),
        ]
    })?;

    // Keyvalue increment child CLIENT span.
    let kv_span = ActiveSpan::start(
        trace_id,
        flags,
        parent_span_id,
        SpanKind::Client,
        "keyvalue increment",
    );
    let count = finish_span_with_result(kv_span, increment_counter(), |count| {
        vec![
            kv_str("keyvalue.key", COUNTER_KEY),
            kv_num("keyvalue.result", *count),
        ]
    })?;

    Ok((count, response_len, outbound_url))
}

/// Settle `span` based on `result`: on `Ok`, attach `ok_attrs(&value)` and
/// mark `Status::Ok`; on `Err`, record the error message on the span before
/// returning the error to the caller.
fn finish_span_with_result<T>(
    span: ActiveSpan,
    result: Result<T>,
    ok_attrs: impl FnOnce(&T) -> Vec<otel::KeyValue>,
) -> Result<T> {
    match result {
        Ok(v) => {
            span.finish_ok(ok_attrs(&v));
            Ok(v)
        }
        Err(e) => {
            span.finish_err(format!("{e:#}"));
            Err::<T, Error>(e)
        }
    }
}

//! OTel metrics export for the request handler.

use crate::otel::{
    Gauge, GaugeDataPoint, Metric, MetricData, MetricNumber, ResourceMetrics, ScopeMetrics, Sum,
    SumDataPoint, Temporality, component_start, export_metrics_bindings, kv_str, now, resource,
    scope,
};

pub(crate) fn export_metrics(count: u64, response_len: usize, outbound_url: &str) {
    // Seed the cumulative start time BEFORE sampling `metric_time`, so on the
    // first export `start_time <= time` holds (OTel spec invariant for
    // cumulative sums).
    let start_time = component_start();
    let metric_time = now();
    let _ = export_metrics_bindings(&ResourceMetrics {
        resource: resource().clone(),
        scope_metrics: vec![ScopeMetrics {
            scope: scope().clone(),
            metrics: vec![
                Metric {
                    name: "http.server.request_count".into(),
                    description: "Total number of HTTP requests handled".into(),
                    unit: "{request}".into(),
                    data: MetricData::U64Sum(Sum {
                        data_points: vec![SumDataPoint {
                            attributes: vec![],
                            value: MetricNumber::U64(count),
                            exemplars: vec![],
                        }],
                        start_time,
                        time: metric_time,
                        temporality: Temporality::Cumulative,
                        is_monotonic: true,
                    }),
                },
                Metric {
                    name: "http.server.response_body.size".into(),
                    description: "Size of the fetched HTTP response body".into(),
                    unit: "By".into(),
                    data: MetricData::U64Gauge(Gauge {
                        data_points: vec![GaugeDataPoint {
                            attributes: vec![kv_str("http.target", outbound_url)],
                            value: MetricNumber::U64(response_len as u64),
                            exemplars: vec![],
                        }],
                        start_time: Some(start_time),
                        time: metric_time,
                    }),
                },
            ],
        }],
    });
}

//! Reusable `OTel` scaffolding for this example.
//!
//! Cached `Resource` and `InstrumentationScope` built once from `wasi:config`,
//! a single trace-correlated log helper ([`otel_log`]), and an RAII
//! [`ActiveSpan`] guard that ends spans even when a `?` early-returns past
//! the explicit completion call.
//!
//! Pulled out of `lib.rs` so the demo flow there reads as a story rather
//! than a sea of OTel plumbing.

use std::collections::BTreeMap;
use std::fmt::Write as _;
use std::sync::OnceLock;

use crate::bindings::wasi::{
    clocks::wall_clock, config::store::get_all, otel, random::random::get_random_bytes,
};

pub(crate) use crate::bindings::wasi::otel::metrics::{
    Gauge, GaugeDataPoint, Metric, MetricData, MetricNumber, ResourceMetrics, ScopeMetrics, Sum,
    SumDataPoint, Temporality, export as export_metrics_bindings,
};
pub(crate) use crate::bindings::wasi::otel::tracing::{
    Event, SpanKind, TraceFlags, outer_span_context,
};
pub(crate) use crate::bindings::wasi::otel::types::KeyValue;

const PKG_NAME: &str = env!("CARGO_PKG_NAME");
const PKG_VERSION: &str = env!("CARGO_PKG_VERSION");

/// Config-key prefix that gets merged into the OTel `Resource` attributes.
/// Mirrors the upstream `OTEL_RESOURCE_ATTRIBUTES` convention.
const RESOURCE_CONFIG_PREFIX: &str = "otel.resource.";

// --- Time ---

/// Captured at first observation; used as the cumulative-counter start time.
static COMPONENT_START: OnceLock<wall_clock::Datetime> = OnceLock::new();

pub(crate) fn now() -> wall_clock::Datetime {
    wall_clock::now()
}

pub(crate) fn component_start() -> wall_clock::Datetime {
    *COMPONENT_START.get_or_init(now)
}

// --- W3C trace context IDs ---

fn random_hex(bytes: usize) -> String {
    let buf = get_random_bytes(bytes as u64);
    let mut out = String::with_capacity(bytes * 2);
    for b in &buf {
        let _ = write!(out, "{b:02x}");
    }
    out
}

pub(crate) fn new_trace_id() -> String {
    random_hex(16)
}
fn new_span_id() -> String {
    random_hex(8)
}

/// Format a W3C `traceparent` header value: `00-{trace_id}-{span_id}-{flags}`.
pub(crate) fn traceparent(trace_id: &str, span_id: &str, flags: TraceFlags) -> String {
    let flag_byte = u8::from(flags.contains(TraceFlags::SAMPLED));
    format!("00-{trace_id}-{span_id}-{flag_byte:02x}")
}

// --- Encoding helpers ---

/// `wasi:otel/types.value` is JSON-encoded — strings need to be quoted/escaped.
fn json_str(s: &str) -> String {
    serde_json::to_string(s).expect("string is always JSON-encodable")
}

pub(crate) fn kv_str(key: &str, value: &str) -> otel::types::KeyValue {
    otel::types::KeyValue {
        key: key.into(),
        value: json_str(value),
    }
}

pub(crate) fn kv_num(key: &str, value: impl std::fmt::Display) -> otel::types::KeyValue {
    otel::types::KeyValue {
        key: key.into(),
        value: value.to_string(),
    }
}

// --- Resource + InstrumentationScope (cached) ---

static RESOURCE: OnceLock<otel::types::Resource> = OnceLock::new();
static SCOPE: OnceLock<otel::types::InstrumentationScope> = OnceLock::new();

/// Cached OTel `Resource`. Built once on first call by reading `wasi:config`:
/// any key prefixed with `otel.resource.` is merged in (mirrors the upstream
/// `OTEL_RESOURCE_ATTRIBUTES` convention). `service.name` and
/// `service.version` default to the crate name/version unless overridden.
pub(crate) fn resource() -> &'static otel::types::Resource {
    RESOURCE.get_or_init(build_resource)
}

fn build_resource() -> otel::types::Resource {
    // BTreeMap so the wire-format attribute order is deterministic across runs.
    let mut attrs: BTreeMap<String, String> = BTreeMap::new();
    attrs.insert("service.name".into(), PKG_NAME.into());
    attrs.insert("service.version".into(), PKG_VERSION.into());

    match get_all() {
        Ok(config) => {
            for (key, value) in config {
                if let Some(attr_key) = key.strip_prefix(RESOURCE_CONFIG_PREFIX)
                    && !attr_key.is_empty()
                {
                    attrs.insert(attr_key.into(), value);
                }
            }
        }
        Err(e) => eprintln!("warning: failed to read wasi:config for OTel resource: {e:?}"),
    }

    otel::types::Resource {
        attributes: attrs.iter().map(|(k, v)| kv_str(k, v)).collect(),
        schema_url: None,
    }
}

pub(crate) fn scope() -> &'static otel::types::InstrumentationScope {
    SCOPE.get_or_init(|| otel::types::InstrumentationScope {
        name: PKG_NAME.into(),
        version: Some(PKG_VERSION.into()),
        schema_url: None,
        attributes: vec![],
    })
}

// --- Logs ---

/// Emit a trace-correlated INFO log via `wasi:otel/logs`.
pub(crate) fn otel_log(msg: &str, trace_id: &str, span_id: &str, flags: TraceFlags) {
    otel::logs::on_emit(&otel::logs::LogRecord {
        timestamp: Some(now()),
        observed_timestamp: None,
        severity_text: Some("INFO".into()),
        severity_number: Some(9),
        body: Some(json_str(msg)),
        attributes: None,
        event_name: None,
        resource: Some(resource().clone()),
        instrumentation_scope: Some(scope().clone()),
        trace_id: Some(trace_id.into()),
        span_id: Some(span_id.into()),
        trace_flags: Some(flags),
    });
}

// --- Span lifecycle ---

/// RAII handle for an in-flight OTel span. `on_start` fires in `start`;
/// `on_end` fires in `Drop`. If the holder is dropped without an explicit
/// `finish_ok` (e.g., a `?` early-returned past it), the span ends with
/// `Status::Error` so the trace exporter sees a complete, accurate picture
/// rather than a leaked, never-ended span.
pub(crate) struct ActiveSpan {
    span_ctx: Option<otel::tracing::SpanContext>,
    parent_span_id: String,
    kind: SpanKind,
    name: &'static str,
    start_time: wall_clock::Datetime,
    attributes: Vec<otel::types::KeyValue>,
    events: Vec<Event>,
    status: otel::tracing::Status,
}

impl ActiveSpan {
    pub(crate) fn start(
        trace_id: &str,
        flags: TraceFlags,
        parent_span_id: impl Into<String>,
        kind: SpanKind,
        name: &'static str,
    ) -> Self {
        let span_ctx = otel::tracing::SpanContext {
            trace_id: trace_id.into(),
            span_id: new_span_id(),
            trace_flags: flags,
            is_remote: false,
            trace_state: vec![],
        };
        otel::tracing::on_start(&span_ctx);
        Self {
            span_ctx: Some(span_ctx),
            parent_span_id: parent_span_id.into(),
            kind,
            name,
            start_time: now(),
            attributes: vec![],
            events: vec![],
            status: otel::tracing::Status::Unset,
        }
    }

    pub(crate) fn span_id(&self) -> &str {
        &self
            .span_ctx
            .as_ref()
            .expect("span_ctx is Some until Drop")
            .span_id
    }

    pub(crate) fn finish_ok(mut self, attributes: Vec<otel::types::KeyValue>) {
        self.attributes = attributes;
        self.status = otel::tracing::Status::Ok;
        // Drop runs `on_end` with the populated state.
    }

    pub(crate) fn finish_ok_with(
        mut self,
        attributes: Vec<otel::types::KeyValue>,
        events: Vec<Event>,
    ) {
        self.attributes = attributes;
        self.events = events;
        self.status = otel::tracing::Status::Ok;
    }

    /// Mark the span as failed with `msg` before it ends. Use this on the
    /// error arm of a fallible call so the span carries the real cause instead
    /// of the generic "span exited via early return" message that Drop would
    /// otherwise apply.
    pub(crate) fn finish_err(mut self, msg: impl Into<String>) {
        self.status = otel::tracing::Status::Error(msg.into());
    }
}

impl Drop for ActiveSpan {
    fn drop(&mut self) {
        let Some(span_ctx) = self.span_ctx.take() else {
            return;
        };
        let status = match std::mem::replace(&mut self.status, otel::tracing::Status::Unset) {
            otel::tracing::Status::Unset => otel::tracing::Status::Error(
                "span exited via early return without explicit completion".into(),
            ),
            other => other,
        };
        otel::tracing::on_end(&otel::tracing::SpanData {
            span_context: span_ctx,
            parent_span_id: std::mem::take(&mut self.parent_span_id),
            span_kind: self.kind,
            name: self.name.into(),
            start_time: self.start_time,
            end_time: now(),
            attributes: std::mem::take(&mut self.attributes),
            events: std::mem::take(&mut self.events),
            links: vec![],
            status,
            instrumentation_scope: scope().clone(),
            dropped_attributes: 0,
            dropped_events: 0,
            dropped_links: 0,
        });
    }
}

//! Outgoing HTTP request with W3C trace context propagation.

use anyhow::{Context, Result, bail};
use wstd::future::FutureExt;
use wstd::http::{Body, Client, HeaderValue, Request};

use crate::config::app_config;
use crate::otel::{TraceFlags, traceparent};

pub(crate) async fn make_outgoing_request(
    trace_id: &str,
    span_id: &str,
    flags: TraceFlags,
) -> Result<Vec<u8>> {
    let cfg = app_config();
    let mut client = Client::new();
    // Per-chunk timers catch a stalled connection mid-stream; the surrounding
    // `.timeout(cfg.request_timeout)` is the hard wall-clock budget so a
    // slowloris-style upstream that drips bytes within the per-chunk window
    // can't stretch the total call to `timeout * N`.
    client.set_first_byte_timeout(cfg.request_timeout);
    client.set_between_bytes_timeout(cfg.request_timeout);

    let header = traceparent(trace_id, span_id, flags);
    let mut builder = Request::get(&cfg.outbound_url).header(
        "traceparent",
        HeaderValue::from_str(&header).context("invalid traceparent header")?,
    );

    // Attach the upstream API token from `secrets.upstream-credentials`.
    // Missing-token paths still work but skip the auth header so the example
    // is exercisable without setting `UPSTREAM_API_TOKEN`.
    if let Some(token) = cfg.upstream_api_token.as_deref() {
        builder = builder.header(
            "authorization",
            HeaderValue::from_str(&format!("Bearer {token}"))
                .context("invalid authorization header")?,
        );
    }

    let request = builder
        .body(Body::empty())
        .context("failed to build outgoing request")?;

    let send_and_read = async {
        let response = client
            .send(request)
            .await
            .context("outgoing request failed")?;

        let status = response.status();
        if !status.is_success() {
            bail!("non-success status from {}: {status}", cfg.outbound_url);
        }

        let mut body = response.into_body();
        let bytes = body
            .contents()
            .await
            .context("failed to read response body")?
            .to_vec();
        Ok(bytes)
    };

    send_and_read
        .timeout(cfg.request_timeout)
        .await
        .with_context(|| format!("outgoing request to {} timed out", cfg.outbound_url))?
}

//! HTML rendering for the demo landing page. Kept out of `lib.rs` so the
//! handler reads as the story.

pub(crate) struct PageData<'a> {
    pub(crate) count: u64,
    pub(crate) response_len: usize,
    pub(crate) outbound_url: &'a str,
    pub(crate) trace_id: &'a str,
    pub(crate) span_id: &'a str,
    pub(crate) otlp_endpoint: &'a str,
}

const PAGE_TEMPLATE: &str = include_str!("../templates/page.html");
const ERROR_TEMPLATE: &str = include_str!("../templates/error.html");

pub(crate) fn render_page(data: &PageData<'_>) -> String {
    PAGE_TEMPLATE
        .replace("{count}", &data.count.to_string())
        .replace("{response_len}", &data.response_len.to_string())
        .replace("{outbound_url}", &html_escape(data.outbound_url))
        .replace("{trace_id}", &html_escape(data.trace_id))
        .replace("{span_id}", &html_escape(data.span_id))
        .replace("{otlp_endpoint}", &html_escape(data.otlp_endpoint))
}

pub(crate) fn render_error(message: &str) -> String {
    ERROR_TEMPLATE.replace("{message}", &html_escape(message))
}

fn html_escape(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    for c in s.chars() {
        match c {
            '&' => out.push_str("&amp;"),
            '<' => out.push_str("&lt;"),
            '>' => out.push_str("&gt;"),
            '"' => out.push_str("&quot;"),
            '\'' => out.push_str("&#39;"),
            _ => out.push(c),
        }
    }
    out
}

use std::io::Cursor;

use image::{ImageFormat, Luma};
