WasmEdge_Result parseJson(void *Data,
                          const WasmEdge_CallingFrameContext *CallingFrameCxt,
                          const WasmEdge_Value *In, WasmEdge_Value *Out) {
  FILE *Fp = fopen("test.json", "r");
  char Buffer[1024];
  fread(Buffer, 1024, 1, Fp);
