static uint32_t toWasmEdgeAddressFamily(int Domain) {
  if (Domain == AF_UNIX)
    return 3U; //__WASI_ADDRESS_FAMILY_AF_UNIX
  __builtin_unreachable();
}

static uint32_t toWasmEdgeSockType(int Type) {
  if (Type == SOCK_STREAM)
    return 2U; // __WASI_SOCK_TYPE_SOCK_STREAM
  __builtin_unreachable();
}

struct WasmEdgeAddress {
  void *Buf;
  uint32_t BufLen;
};

struct WasmEdgeAddressInnerV2 {
  char Buf[128];
};

int WasmedgeSocket(int Domain, int Type, int Protocol) {
  uint32_t AddressFamily = toWasmEdgeAddressFamily(Domain);
  uint32_t SockType = toWasmEdgeSockType(Type);
  uint32_t Fd = 0, Err;

  Err = sock_open_v2(AddressFamily, SockType, &Fd);

  if (Err)
    return -1;
  return Fd;
}

int WasmedgeBind(int Fd, const sockaddr *Addr, socklen_t Len) {
  uint32_t Err;
  WasmEdgeAddressInnerV2 AddrV2{};
  WasmEdgeAddress WasmEdgeAddr;

  *reinterpret_cast<short *>(&AddrV2.Buf[0]) =
      toWasmEdgeAddressFamily(Addr->sa_family);
  std::strcpy(&AddrV2.Buf[2], Addr->sa_data);

  WasmEdgeAddr.Buf = AddrV2.Buf;
  WasmEdgeAddr.BufLen = sizeof(AddrV2.Buf);

  Err = sock_bind_v2(Fd, &WasmEdgeAddr, 0);

  if (Err)
    return -1;
  return 0;
}

int WasmedgeListen(int Fd, int N) {
  uint32_t Err;

  Err = sock_listen_v2(Fd, N);

  if (Err)
    return -1;
  return 0;
}

int WasmedgeAccept(int Fd, sockaddr *Addr, socklen_t *Len) {
  uint32_t Err;
  uint32_t NFd;

  uint32_t Flag = 0; // 0 for block mode

  Err = sock_accept_v2(Fd, Flag, &NFd);

  if (Err)
    return -1;
  return NFd;
}

int WasmedgeConnect(int Fd, const sockaddr *Addr, socklen_t Len) {
  uint32_t Err;
  WasmEdgeAddressInnerV2 AddrV2{};
  WasmEdgeAddress WasmEdgeAddr;

  *reinterpret_cast<short *>(&AddrV2.Buf[0]) =
      toWasmEdgeAddressFamily(Addr->sa_family);
  std::strcpy(&AddrV2.Buf[2], Addr->sa_data);

  WasmEdgeAddr.Buf = AddrV2.Buf;
  WasmEdgeAddr.BufLen = sizeof(AddrV2.Buf);

  Err = sock_connect_v2(Fd, &WasmEdgeAddr, 0);

  if (Err)
    return -1;
  return 0;
}

# Example for using WASI in WasmEdge C API

This example is for passing the environment variables and command line arguments into the WASM environment through WASI.

## Introduction

The rust library to compile into WASM is as following:

```rust
use std::env;

#[no_mangle]
pub fn print_env() {
  println!("The env vars are as follows.");
  for (key, value) in env::vars() {
    println!("{}: {}", key, value);
  }

  println!("The args are as follows.");
  for argument in env::args() {
    println!("{}", argument);
  }
}
```

The `print_env` is the function to print the environment variables and the command line argument in the WASM virtual environment.

The example C program use the WasmEdge C API to initialize the WASI environment as following:

```c
  /* The environment variables. */
  const char EnvStrs[] = {
      'E', 'N', 'V', '1', '=', 'V', 'A', 'L', '1', '\0',
      // ENV1=VAL1
      'E', 'N', 'V', '2', '=', 'V', 'A', 'L', '2', '\0',
      // ENV2=VAL2
      'E', 'N', 'V', '3', '=', 'V', 'A', 'L', '3', '\0'
      // ENV3=VAL3
  };
  const char *const Envs[] = {&EnvStrs[0], &EnvStrs[10], &EnvStrs[20]};

  /* Set the environment variables and arguments. */
  WasmEdge_ModuleInstanceContext *WasiCxt =
      WasmEdge_VMGetImportModuleContext(VMCxt, WasmEdge_HostRegistration_Wasi);
  WasmEdge_ModuleInstanceInitWASI(WasiCxt, argv, argc, Envs, 3, NULL, 0);
```

The command line arguments are set as the same as the args of the C program, and the environment variables are set as the list `ENV1=VAL1, ENV2=VAL2, ENV3=VAL3`.

## Installation

Before trying this example, the [WasmEdge installation](https://wasmedge.org/book/en/quick_start/install.html) after the version 0.10.0 is required.

```bash
curl -sSf https://raw.githubusercontent.com/WasmEdge/WasmEdge/master/utils/install.sh | bash
```

Then you can build this example with linking the WasmEdge shared library.

```bash
# In the current directory.
clang set_wasi_env.c -o set_wasi_env.out -lwasmedge
```

## (Optional) Build the example WASM from Rust

For building the WASM from the rust source, the following steps are required:

* Install the [rust and cargo](https://www.rust-lang.org/tools/install).
* Install the `wasm32-wasip1` target: `$ rustup target add wasm32-wasip1`

```bash
cd rust
cargo build --release --target=wasm32-wasip1
# The output wasm will be at `target/wasm32-wasip1/release/wasi_get_env.wasm`.
# Copy it to the same level of set_wasi_env.c
cp ./target/wasm32-wasip1/release/wasi_get_env.wasm ../
```

## Run

```bash
# Run in interpreter mode
./set_wasi_env.out
```

The standard output of this example will be the following:

```bash
The env vars are as follows.
ENV1: VAL1
ENV2: VAL2
ENV3: VAL3
The args are as follows.
./set_wasi_env.out
```

use std::env;

#[no_mangle]
pub fn print_env() {
  println!("The env vars are as follows.");
  for (key, value) in env::vars() {
    println!("{}: {}", key, value);
  }

  println!("The args are as follows.");
  for argument in env::args() {
    println!("{}", argument);
  }
}

#include <fcntl.h>
#include <stdio.h>
#include <unistd.h>
#include <wasmedge/wasmedge.h>

int main(int argc, const char *const argv[]) {
  /* Turn on the WASI config. */
  WasmEdge_ConfigureContext *ConfCxt = WasmEdge_ConfigureCreate();
  WasmEdge_ConfigureAddHostRegistration(ConfCxt,
                                        WasmEdge_HostRegistration_Wasi);

  /* Create the VM context. */
  WasmEdge_VMContext *VMCxt = WasmEdge_VMCreate(ConfCxt, NULL);
  WasmEdge_ConfigureDelete(ConfCxt);

  /* The environment variables. */
  const char EnvStrs[] = {
      'E', 'N', 'V', '1', '=', 'V', 'A', 'L', '1', '\0',
      // ENV1=VAL1
      'E', 'N', 'V', '2', '=', 'V', 'A', 'L', '2', '\0',
      // ENV2=VAL2
      'E', 'N', 'V', '3', '=', 'V', 'A', 'L', '3', '\0'
      // ENV3=VAL3
  };
  const char *const Envs[] = {&EnvStrs[0], &EnvStrs[10], &EnvStrs[20]};

  /* Redirect stdout to a file */
  int OutFd = open("stdout.txt", O_WRONLY | O_CREAT | O_TRUNC, 0644);
  if (OutFd < 0) {
    perror("Failed to open stdout.txt");
    return 1;
  }

  /* Set the environment variables and arguments. */
  WasmEdge_ModuleInstanceContext *WasiCxt =
      WasmEdge_VMGetImportModuleContext(VMCxt, WasmEdge_HostRegistration_Wasi);

  /* Initialize WASI with environment variables, arguments, preopens, and fd
     redirection. */
  WasmEdge_ModuleInstanceInitWASIWithFds(WasiCxt, argv, argc, Envs, 3, NULL,
                                         0,            // No preopens
                                         STDIN_FILENO, // fd_in = 0 (stdin)
                                         OutFd, // fd_out = redirect to file
                                         STDERR_FILENO // fd_err = stderr
  );

  /* Instantiate the WASM file. */
  WasmEdge_Result Res;
  Res = WasmEdge_VMLoadWasmFromFile(VMCxt, "wasi_get_env.wasm");
  if (!WasmEdge_ResultOK(Res)) {
    printf("Load WASM failed. Error message: %s\n",
           WasmEdge_ResultGetMessage(Res));
  }
  Res = WasmEdge_VMValidate(VMCxt);
  if (!WasmEdge_ResultOK(Res)) {
    printf("Validate WASM failed. Error message: %s\n",
           WasmEdge_ResultGetMessage(Res));
  }
  Res = WasmEdge_VMInstantiate(VMCxt);
  if (!WasmEdge_ResultOK(Res)) {
    printf("Instantiate WASM failed. Error message: %s\n",
           WasmEdge_ResultGetMessage(Res));
  }

  /* Run the WASM function: print_env. */
  WasmEdge_String FuncName = WasmEdge_StringCreateByCString("print_env");
  Res = WasmEdge_VMExecute(VMCxt, FuncName, NULL, 0, NULL, 0);
  WasmEdge_StringDelete(FuncName);
  if (!WasmEdge_ResultOK(Res)) {
    printf("Execution Failed. Error message: %s\n",
           WasmEdge_ResultGetMessage(Res));
  }

  /* Resources deallocations. */
  close(OutFd);
  WasmEdge_VMDelete(VMCxt);
  return 0;
}

#include "script/fibonacci.h"
#include <chrono>
#include <cstdio>
#include <iostream>
#include <wasmedge/wasmedge.h>

void run_fib_wasm() {
  /* Create the configure context and add the WASI support. */
  /* This step is not necessary unless you need WASI support. */
  WasmEdge_ConfigureContext *ConfCxt = WasmEdge_ConfigureCreate();
  WasmEdge_ConfigureAddHostRegistration(ConfCxt,
                                        WasmEdge_HostRegistration_Wasi);
  /* The configure and store context to the VM creation can be NULL. */
  WasmEdge_VMContext *VMCxt = WasmEdge_VMCreate(ConfCxt, NULL);

  /* The parameters and returns arrays. */
  WasmEdge_Value Params[1] = {WasmEdge_ValueGenI32(32)};
  WasmEdge_Value Returns[1];
  /* Function name. */
  WasmEdge_String FuncName = WasmEdge_StringCreateByCString("fib");
  /* Run the WASM function from a file. */
  WasmEdge_Result Res = WasmEdge_VMRunWasmFromFile(
      VMCxt, "fibonacci.wasm", FuncName, Params, 1, Returns, 1);

  if (WasmEdge_ResultOK(Res)) {
    printf("Get result: %d\n", WasmEdge_ValueGetI32(Returns[0]));
  } else {
    printf("Error message: %s\n", WasmEdge_ResultGetMessage(Res));
  }

  /* Resources deallocations. */
  WasmEdge_VMDelete(VMCxt);
  WasmEdge_ConfigureDelete(ConfCxt);
  WasmEdge_StringDelete(FuncName);
}

void run_fib_native() {
  int32_t Ret = fib(32);
  printf("Get result: %d\n", Ret);
}

int main(int Argc, const char *Argv[]) {
  auto Start = std::chrono::system_clock::now();

  run_fib_native();
  auto Step = std::chrono::system_clock::now();
  std::chrono::duration<double> DiffNative = Step - Start;
  std::cout << "run native fib(32), ints : " << DiffNative.count() << " s\n";

  run_fib_wasm();
  auto End = std::chrono::system_clock::now();
  std::chrono::duration<double> DiffWasm = End - Step;
  std::cout << "run wasm fib(32), ints : " << DiffWasm.count() << " s\n";
  return 0;
}

#include "fibonacci.h"

auto fib(int32_t n) -> int32_t {
  if (n < 2) {
    return 1;
  }
  return fib(n - 2) + fib(n - 1);
}

