use anyhow::Result;
use xline_client::{Client, ClientOptions};

#[tokio::main]
async fn main() -> Result<()> {
    // the name and address of all curp members
    let curp_members = ["10.0.0.1:2379", "10.0.0.2:2379", "10.0.0.3:2379"];

    let mut client = Client::connect(curp_members, ClientOptions::default())
        .await?
        .cluster_client();

    // send a linearizable member list request
    let resp = client.member_list(true).await?;
    println!("members: {:?}", resp.members);

    // whether the added member is a learner.
    // the learner does not participate in voting and will only catch up with the progress of the leader.
    let is_learner = true;

    // add a normal node into the cluster
    let resp = client.member_add(["127.0.0.1:2379"], is_learner).await?;
    let added_member = resp.member.unwrap();
    println!("members: {:?}, added: {}", resp.members, added_member.id);

    if is_learner {
        // promote the learner to a normal node
        let resp = client.member_promote(added_member.id).await?;
        println!("members: {:?}", resp.members);
    }

    // update the peer_ur_ls of the added member if the network topology has changed.
    let resp = client
        .member_update(added_member.id, ["127.0.0.2:2379"])
        .await?;
    println!("members: {:?}", resp.members);

    // remove the member from the cluster if it is no longer needed.
    let resp = client.member_remove(added_member.id).await?;
    println!("members: {:?}", resp.members);

    Ok(())
}

//! An example to show how the errors are organized in `xline-client`
use anyhow::Result;
use xline_client::{error::XlineClientError, types::kv::PutOptions, Client, ClientOptions};
use xlineapi::execute_error::ExecuteError;

#[tokio::main]
async fn main() -> Result<()> {
    // the name and address of all curp members
    let curp_members = ["10.0.0.1:2379", "10.0.0.2:2379", "10.0.0.3:2379"];

    let client = Client::connect(curp_members, ClientOptions::default())
        .await?
        .kv_client();

    // We try to update the key using its previous value.
    // It should return an error and it should be `key not found`
    // as we did not add it before.
    let resp = client
        .put(
            "key",
            "",
            Some(PutOptions::default().with_ignore_value(true)),
        )
        .await;
    let err = resp.unwrap_err();

    // We match the inner error returned by the Curp server.
    // The command should failed at execution stage.
    let XlineClientError::CommandError(ee) = err else {
        unreachable!("the propose error should be an Execute error, but it is {err:?}")
    };

    assert!(
        matches!(ee, ExecuteError::KeyNotFound),
        "the return result should be `KeyNotFound`"
    );
    println!("got error: {ee}");

    Ok(())
}

use anyhow::Result;
use xline_client::{
    types::kv::{Compare, CompareResult, DeleteRangeOptions, PutOptions, TxnOp, TxnRequest},
    Client, ClientOptions,
};

#[tokio::main]
async fn main() -> Result<()> {
    // the name and address of all curp members
    let curp_members = ["10.0.0.1:2379", "10.0.0.2:2379", "10.0.0.3:2379"];

    let client = Client::connect(curp_members, ClientOptions::default())
        .await?
        .kv_client();

    // put
    client.put("key1", "value1", None).await?;
    client.put("key2", "value2", None).await?;

    // range
    let resp = client.range("key1", None).await?;

    if let Some(kv) = resp.kvs.first() {
        println!(
            "got key: {}, value: {}",
            String::from_utf8_lossy(&kv.key),
            String::from_utf8_lossy(&kv.value)
        );
    }

    // delete
    let resp = client
        .delete(
            "key1",
            Some(DeleteRangeOptions::default().with_prev_kv(true)),
        )
        .await?;

    for kv in resp.prev_kvs {
        println!(
            "deleted key: {}, value: {}",
            String::from_utf8_lossy(&kv.key),
            String::from_utf8_lossy(&kv.value)
        );
    }

    // txn
    let txn_req = TxnRequest::new()
        .when(&[Compare::value("key2", CompareResult::Equal, "value2")][..])
        .and_then(
            &[TxnOp::put(
                "key2",
                "value3",
                Some(PutOptions::default().with_prev_kv(true)),
            )][..],
        )
        .or_else(&[TxnOp::range("key2", None)][..]);

    let _resp = client.txn(txn_req).await?;
    let resp = client.range("key2", None).await?;
    // should print "value3"
    if let Some(kv) = resp.kvs.first() {
        println!(
            "got key: {}, value: {}",
            String::from_utf8_lossy(&kv.key),
            String::from_utf8_lossy(&kv.value)
        );
    }

    // compact
    let rev = resp.header.unwrap().revision;
    let _resp = client.compact(rev, false).await?;

    Ok(())
}

use anyhow::Result;
use xline_client::{Client, ClientOptions};

#[tokio::main]
async fn main() -> Result<()> {
    // the name and address of all curp members
    let curp_members = ["10.0.0.1:2379", "10.0.0.2:2379", "10.0.0.3:2379"];

    let mut client = Client::connect(curp_members, ClientOptions::default())
        .await?
        .lease_client();

    // grant new lease
    let resp1 = client.grant(60, None).await?;
    let resp2 = client.grant(60, None).await?;
    let lease_id1 = resp1.id;
    let lease_id2 = resp2.id;
    println!("lease id 1: {}", lease_id1);
    println!("lease id 2: {}", lease_id2);

    // get the ttl of lease1
    let resp = client.time_to_live(lease_id1, false).await?;

    println!("remaining ttl: {}", resp.ttl);

    // keep alive lease2
    let (mut keeper, mut stream) = client.keep_alive(lease_id2).await?;

    if let Some(resp) = stream.message().await? {
        println!("new ttl: {}", resp.ttl);
    }

    // keep alive lease2 again using the keeper
    keeper.keep_alive()?;

    // list all leases
    for lease in client.leases().await?.leases {
        println!("lease: {}", lease.id);
    }

    // revoke the leases
    let _resp = client.revoke(lease_id1).await?;
    let _resp = client.revoke(lease_id2).await?;

    Ok(())
}

use anyhow::Result;
use xline_client::{
    clients::Xutex,
    types::kv::{Compare, CompareResult, PutOptions, TxnOp},
    Client, ClientOptions,
};

#[tokio::main]
async fn main() -> Result<()> {
    // the name and address of all curp members
    let curp_members = ["10.0.0.1:2379", "10.0.0.2:2379", "10.0.0.3:2379"];

    let client = Client::connect(curp_members, ClientOptions::default()).await?;

    let lock_client = client.lock_client();
    let kv_client = client.kv_client();

    let mut xutex = Xutex::new(lock_client, "lock-test", None, None).await?;
    // when the `xutex_guard` drop, the lock will be unlocked.
    let xutex_guard = xutex.lock_unsafe().await?;

    let txn_req = xutex_guard
        .txn_check_locked_key()
        .when([Compare::value("key2", CompareResult::Equal, "value2")])
        .and_then([TxnOp::put(
            "key2",
            "value3",
            Some(PutOptions::default().with_prev_kv(true)),
        )])
        .or_else(&[]);

    let _resp = kv_client.txn(txn_req).await?;

    Ok(())
}

use anyhow::Result;
use xline_client::{Client, ClientOptions};

#[tokio::main]
async fn main() -> Result<()> {
    // the name and address of all curp members
    let curp_members = ["10.0.0.1:2379", "10.0.0.2:2379", "10.0.0.3:2379"];

    let mut client = Client::connect(curp_members, ClientOptions::default())
        .await?
        .maintenance_client();

    // snapshot
    let mut msg = client.snapshot().await?;
    let mut snapshot = vec![];
    loop {
        if let Some(resp) = msg.message().await? {
            snapshot.extend_from_slice(&resp.blob);
            if resp.remaining_bytes == 0 {
                break;
            }
        }
    }
    println!("snapshot size: {}", snapshot.len());

    Ok(())
}

